int closestShape;

int dateToDay(vec3 date){
	int d = 0;
	switch(int(date.y)){
		case 2:
		d += 31;
		break;
		case 3:
		d += 60;
		break;
		case 4:
		d += 91;
		break;
		case 5:
		d += 121;
		break;
		case 6:
		d += 152;
		break;
		case 7:
		d += 182;
		break;
		case 8:
		d += 213;
		break;
		case 9:
		d += 244;
		break;
		case 10:
		d += 274;
		break;
		case 11:
		d += 305;
		break;
		case 12:
		d += 335;
		break;
	}

	d += int(date.x);

	return d;
}

vec3 getCalendarColor(vec3 date, bool charging){
	return vec3(255, 255, 153) / 255.0;
}

float timeToFactor(float time){
	return time / 86400.0;
}

float getSunrise(vec3 date){
	float day = float(dateToDay(date));
	day /= 366.0;

	return 0.3201 + 0.0396 * cos(6.28 * day);
}

float getSundown(vec3 date){
	float day = float(dateToDay(date));
	day /= 366.0;

	return 0.8253 + 0.0837 * -cos(6.28 * day);
}

vec3 getSkyColor(float t, float rise, float down, vec3 lightColor){
	if(t < rise || t > down + 0.05){
		return vec3(0, 0, 0);
	}else if(t < rise + 0.05){
		return vec3((t - rise) * 8.0, (t - rise) * 8.0, (t - rise) * 8.0);
	}else if(t < rise + 0.2){
		return vec3(0.4, 0.4, 0.4);
	}else if(t < rise + 0.25){
		return vec3((t - rise - 0.2) + 0.4, (t - rise - 0.2) + 0.4, (t - rise - 0.2) * 10.0 + 0.4);
	}else if(t > down - 0.1){
		//return vec3((t - down - 0.05) * -4.5, (t - down - 0.01) * -7.5, (t - down) * -18);
		return mix(mix(vec3(0.45, 0.45, 0.9), vec3(1.0, 0.5, 0.4), smoothstep(down - 0.1, down, t)), vec3(0.0), smoothstep(down, down + 0.05, t));
	}else{
		return vec3(0.45, 0.45, 0.9);
	}
}

vec3 getSunColor(float t, float rise, float down){
	if(t < rise || t > down){
		return vec3(0);
	}else if(t < rise + 0.15){
		return vec3((t - rise) * 6.666);
	}else if(t > down - 0.05){
		return vec3((t - down) * -20.0, (t - down) * -10.0, 0);
	}else if(t > down - 0.1){
		return vec3(1.0, (t - down) * -10.0, (t - down + 0.05) * -20.0);
	}else{
		return vec3(1);
	}
}

float getfogStart(float t, float rise, float down){
	return -7.0 * cos(6.28 * (t - rise)) + 13.0;
}

float getfogEnd(float t, float rise, float down){
	return -35.0 * cos(6.28 * (t - rise)) + 65.0;
}

float getShadowStrength(float t, float rise, float down){
	if(t < rise + 0.2 || t > down){
		return 0.1;
	}else if(t < rise + 0.25){
		return (t - rise - 0.2) * 20.0;
	}else if(t > down - 0.1){
		return (t - down) * -10.0;
	}else{
		return 1.0;
	}
}

vec3 rot3(vec3 p, vec3 axis, float angle){
	return mix(dot(axis, p) * axis, p, cos(angle)) + cross(axis, p) * sin(angle);
}

vec3 rot2Z(vec3 p, float angle){ //rotates on z axis
	float s = sin(angle);
	float c = cos(angle);
	mat2 m = mat2(c, -s, s, c);
	p.yx *= m;
	return p;
}

vec3 rot2(vec3 p, float angle){ //rotates on y axis
	float s = sin(angle);
	float c = cos(angle);
	mat2 m = mat2(c, -s, s, c);
	p.zx *= m;
	return p;
}

float distBox(vec3 p, vec3 dims){
  vec3 q = abs(p) - dims;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}

float map(vec3 p){
	p = rot2(p, 5.6);

	vec3 q = mod(p, 15.0);

	q.y = p.y;
	q.x = p.x;

	float[6] dists;

	dists[0] = p.y + 2.0; //ground

	float x = -1.0;
	float y = 7.0;

	dists[1] = distBox(q - vec3(x, 0, y), vec3(0.2, 6, 0.2));
	dists[2] = distBox(q - vec3(x - 0.9, 6, y), vec3(1.1, 0.2, 0.4));
	dists[3] = distBox(q - vec3(x - 1.3, 5.7, y), vec3(0.6, 0.1, 0.3));

	dists[4] = distBox(q - vec3(-1 - 9, -1.95, 7), vec3(8, 0.1, 20)); //road

	dists[5] = distBox(q - vec3(-1 - 9, -1.94, 7), vec3(0.1, 0.1, 1)); //strip

	float d = dists[0];

	closestShape = 0;

	for(int i = 1; i < 6; i++){
		if(dists[i] < d){
			d = dists[i];
			closestShape = i;
		}
	}

	return d;
}

float softshadow(in vec3 ro, in vec3 rd, float mint, float maxt, float w)
{
    float res = 1.0;
    float t = mint;
    for( int i=0; i<256 && t<maxt; i++ )
    {
        float h = map(ro + t*rd);
        res = min( res, h/(w*t) );
        t += clamp(h, 0.005, 0.50);
        if( res<-1.0 || t>maxt ) break;
    }
    res = max(res,-1.0);
    return 0.25*(1.0+res)*(1.0+res)*(2.0-res);
}

vec3 getNormal(vec3 p){
	vec2 d = vec2(0.01, 0.0);
	float gx = map(p+d.xyy) - map (p - d.xyy);
	float gy = map(p + d.yxy) - map(p - d.yxy);
	float gz = map(p + d.yyx) - map (p - d.yyx);
	vec3 normal = vec3(gx, gy, gz);
	return normalize(normal);
}

vec4 doLightingDay(vec3 lightColor, vec3 direction, vec3 c, vec3 normal, vec3 rayPos, vec3 ro, float shadowStrength){
	vec4 col = vec4(c, 1.0);

	vec4 ambient = 0.1 * vec4(lightColor, 1.0) * col;

	//Diffuse component
	vec3 lightDir = normalize(-direction);
    float diff = max(dot(normalize(normal), lightDir), 0.0);
	vec4 diffuse = diff * vec4(lightColor, 1.0) * col;

	//Specular component
	vec3 viewDir = normalize(ro - rayPos);
	vec3 halfwayDir = normalize(lightDir + viewDir);
	float spec = pow(max(dot(normalize(normal), halfwayDir), 0.0), 128.0);
	vec4 specular = 0.5 * vec4(lightColor, 1.0) * spec * vec4(lightColor, 1.0);

	//No attenuation is required

	float shad = softshadow(rayPos, -direction, 0.001, 2.0, 0.5);
	float strength = (1.0 - shadowStrength) + shad * shadowStrength;
	diffuse *= strength;
	specular *= strength;

	return ambient + specular + diffuse;
}

vec3 groundPalette(vec3 date){
	float t = float(dateToDay(date))/366.0;

    // Seasonal colors
    vec3 winter = vec3(0.2, 0.16, 0.16);    // Grayish-brown for winter
    vec3 spring = vec3(0.19, 0.42, 0.1);    // Green for spring
    vec3 summer = vec3(0.33, 0.29, 0.19);    // Drier green for summer
    vec3 autumn = vec3(0.2, 0.12, 0.1);   // Brown for autumn

    // Normalize t to a range of 0 to 1
    t = mod(t, 1.0);  // Ensure t loops over a full cycle

    // Seasonal transitions using smooth step
    if (t < 0.25) {
        // Winter to spring transition (0 to 0.25)
        return mix(winter, spring, smoothstep(0.0, 0.25, t));
    } else if (t < 0.5) {
        // Spring to summer transition (0.25 to 0.5)
        return mix(spring, summer, smoothstep(0.25, 0.5, t));
    } else if (t < 0.75) {
        // Summer to autumn transition (0.5 to 0.75)
        return mix(summer, autumn, smoothstep(0.5, 0.75, t));
    } else {
        // Autumn to winter transition (0.75 to 1.0)
        return mix(autumn, winter, smoothstep(0.75, 1.0, t));
    }
}


vec4 doLightingNight(vec3 lightColor, vec3 c, vec3 normal, vec3 rayPos, vec3 ro){
	rayPos = rot2(rayPos, 5.6);

	float x = -1.0;
	float y = 7.0;

	vec4 col = vec4(c, 1.0);

	vec4 fff = vec4(0);

	for(int i = -30; i < 120; i += 15){
		vec3 lightPos = vec3(x - 1.3, 5.7, y + float(i));
		vec3 lightDir = normalize(lightPos - rayPos);

		//Spotlight stuff
		float theta = dot(lightDir, vec3(0, 1, 0));
		float epsilon = (0.9902 - 0.7); //cutoff values, inner - outer, cosine
		float intensity = clamp((theta - 0.7) / epsilon, 0.0, 1.0);
		//intensity = 1;

		//Ambient component
		vec4 ambient = 0.1 * vec4(lightColor, 1.0) * col;

		//Diffuse component
		float diff = max(dot(normal, lightDir), 0.0);
		vec4 diffuse = intensity * diff * vec4(lightColor, 1.0) * col;

		//Specular component
		vec3 viewDir = normalize(ro - rayPos);
		vec3 halfwayDir = normalize(lightDir + viewDir);
		float spec = pow(max(dot(normalize(normal), halfwayDir), 0.0), 128.0);
		vec4 lightCol = vec4(min(1.5, lightColor.x), min(1.5, lightColor.y), min(1.5, lightColor.z), 1.0);
		vec4 specular = 0.5 * intensity * lightCol * spec * lightCol;

		//Apply attenuation
		float distance = length(lightPos - rayPos);
		float attenuation = 1.0 / (1.0 + 0.01 * distance + 0.0057 * (distance * distance));  

		ambient  *= attenuation; 
		diffuse  *= attenuation;
		specular *= attenuation;

		fff += ambient + diffuse + specular;
	}

	return fff;
}

vec4 doLighting(vec3 lightColor, vec3 sunColor, vec3 sunDir, vec3 c, vec3 normal, vec3 rayPos, vec3 ro, float shadowStrength, float timeFactor){	
	if(timeFactor == 0.0){
		return doLightingNight(lightColor, c, normal, rayPos, ro);
	}else if(timeFactor == 1.0){
		return doLightingDay(sunColor, sunDir, c, normal, rayPos, ro, shadowStrength);
	}else{
		return mix(doLightingNight(lightColor, c, normal, rayPos, ro), doLightingDay(sunColor, sunDir, c, normal, rayPos, ro, shadowStrength), timeFactor);
	}
}

// Simple hash function for pseudo-random number generation
float random(vec3 p) {
    return fract(sin(dot(p, vec3(12.9898, 78.233, 45.164))) * 43758.5453);
}

vec4 doStars(vec3 p, float strength) {

	if(random(p) > 0.999){
		return vec4(random(p * 11.2)) * strength;
	}

    // If no star found at this position, return black (background)
    return vec4(0.0, 0.0, 0.0, 1.0);
}


float calculateFogFactor(float depth, float start, float end){
	float fogFactor = clamp((depth - start) / (end - start), 0.0, 1.0);
	return fogFactor;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord){  
    fragCoord = (fragCoord.xy / iResolution.xy) * 2.0 - 1.0;
	vec2 fragPos = vec2(fragCoord.x * iResolution.x/iResolution.y, fragCoord.y);

	//float camPos = 5 * sin(0.005*iTime);
	float camPos = 0.0;

	vec3 ro = vec3(camPos, 3, -3); //cam pos, ray origin
	vec3 rd = normalize(vec3(fragPos, 1)); //ray direction

	//vec3 date = vec3(7, 4, 2024);
	//vec3 time = vec3(3, 0, 0);

	vec3 date = iDate.zyx;
	float time = iDate.w;

	bool charging = false;

	//vec3 groundColor = vec3(0.2, 0.12, 0.1);

	//float timeFactor = fract(0.1*iTime);
	float timeFactor = fract(timeToFactor(time));

	float sunrise = getSunrise(date);
	float sundown = getSundown(date);

	bool lightsOn = false;
	if(timeFactor < sunrise + 0.08 || timeFactor > sundown - 0.07){
		lightsOn = true;
	}

	float fogStart = getfogStart(timeFactor, sunrise, sundown);
	float fogEnd = getfogEnd(timeFactor, sunrise, sundown);

	vec3 lightColor = getCalendarColor(date, charging);

	vec3 skyColor = getSkyColor(timeFactor, sunrise, sundown, lightColor) * ((1.0 - smoothstep(-0.2, 2.1, fragPos.y)) + 0.2);

	float t = 0.0; //distance

	int i;
	for(i = 0; i < 80; i++){
		vec3 p = ro + t * rd; //position

		float d = map(p);

		t += d;

		if(d < 0.0005 || t > fogEnd){
			break;
		}
	}

	vec3 selectedColor = vec3(0.0);

	switch(closestShape){
		case 0:
		vec3 groundColor = groundPalette(date) * texture(iChannel0, ((ro + t * rd)/16.0).xz).xyz;
		selectedColor = groundColor;
		break;
		case 1:
		case 2:
		vec3 metalColor = vec3(0.4);
		selectedColor = metalColor;
		break;
		case 3:
		//vec3 lightColor = vec3(1, 1, 0.6);
		selectedColor = lightColor;
		break;
		case 4:
		vec3 roadColor = vec3(0.1, 0.1, 0.1) * min(texture(iChannel0, ((ro + t * rd)/32.0).xz).xyz + vec3(0.5), 1.0);
		selectedColor = roadColor;
		break;
		case 5:
		vec3 stripColor = vec3(0.8, 0.7, 0);
		selectedColor = stripColor;
		break;
	}

	if(t > fogEnd){
		fragColor = vec4(skyColor, 1.0);
		if((timeFactor < sunrise || timeFactor > sundown) && fragPos.y > 0.0){
			vec3 rayPos = ro + t * rd;
			float strength = 1.0;
			if(timeFactor < sunrise && timeFactor > sunrise - 0.05){
				strength = (timeFactor - sunrise) * -20.0;
			}else if(timeFactor > sundown && timeFactor < sundown + 0.05){
				strength = (timeFactor - sundown) * 20.0;
			}
			fragColor += doStars(vec3(fragPos, 0.0), strength);
		}
	}else if(closestShape == 3 && lightsOn){
		fragColor = vec4(selectedColor * 0.6, 1.0);

		fragColor = mix(fragColor, vec4(skyColor, 1.0), max(0.0, calculateFogFactor(t, fogStart, fogEnd) - 0.5));
	}else{
		vec3 sunColor = getSunColor(timeFactor, sunrise, sundown);
		vec3 sunDir = vec3((timeFactor - sundown + ((sundown - sunrise)/2.0)) * 12.0, -1, 0.2);
		float shadowStrength = getShadowStrength(timeFactor, sunrise, sundown);

		vec3 rayPos = ro + t * rd;
		vec3 normal = getNormal(rayPos);
		fragColor = vec4(0.0);
		if(lightsOn){
			fragColor += doLightingNight(lightColor, selectedColor, normal, rayPos, ro);
		}if(timeFactor > sunrise && timeFactor < sundown){
			fragColor += doLightingDay(sunColor, sunDir, selectedColor, normal, rayPos, ro, shadowStrength);
		}
		//fragColor = doLighting(lightColor, sunColor, sunDir, selectedColor, normal, rayPos, ro, shadowStrength, 1.0);

		//apply fog
		fragColor = mix(fragColor, vec4(skyColor, 1.0), calculateFogFactor(t, fogStart, fogEnd));
	}
}
